export function encodeTwilioMedia(
  streamSid: string,
  mulawAudio: Uint8Array,
): string {
  return JSON.stringify({
    event: "media",
    streamSid,
    media: {
      payload: Buffer.from(mulawAudio).toString("base64"),
    },
  });
}
